#include <iostream>
#include <map>
#include <set>
#include <vector>
using namespace std;

int main() {
    vector<int> values = {2, 2, 3};
    map<int, int> frequency;
    set<int> distinct;
    for (int value : values) {
        ++frequency[value];
        distinct.insert(value);
    }
    for (auto [key, cnt] : frequency) cout << key << ' ' << cnt << '\n';
    return 0;
}

#include <iostream>
#include <queue>
#include <vector>
using namespace std;

int main() {
    priority_queue<int, vector<int>, greater<int>> minHeap;
    minHeap.push(5);
    minHeap.push(1);
    minHeap.push(4);
    while (!minHeap.empty()) {
        cout << minHeap.top() << ' ';
        minHeap.pop();
    }
    return 0;
}
